import os as _os
_ROOT = _os.path.normpath(_os.path.join(_os.path.dirname(_os.path.abspath(__file__)), '..', '..', '..'))   # THE PORTABLE REPO (2026-09-15): the repo root from this file's own place
#!/usr/bin/env python3
# THE DEUTERONOMY WALK sitting 15 — CHAPTERS 17-18, LEAN (2026-09-24): THE FOUR RECORDS of the lean form in ONE call — the map's AS BUILT (short: the departures and
# the lessons, with the timing table), the state doc's #211, the recovery page (section 2 under its cap), the memory (the index line and the walk note) — plus the
