reg = rd(f'{SP}/ch17_register.out'); DECL, DEBTN, FAILS = (int(x) for x in re.search(r'DECLARED (\d+) / DEBT (\d+) / FAILS (\d+)', reg).groups()) if re.search(r'DECLARED (\d+) / DEBT (\d+) / FAILS (\d+)', reg) else (int(re.search(r'DECLARED (\d+)', reg).group(1)), -1, -1)
UIDS = ['deu_17_courts_king', 'deu_18_levi_prophet']
VT = {u: re.search(r'TEXT LAYER GREEN: (\d+) steps, (\d+) scenarios', rd(f'{SP}/ch17_vt_{u}.out')).groups() for u in UIDS}
RP = {u: len(re.findall(r'\bPASS\b', rd(f'{SP}/ch17_ritual_{u}.out'))) for u in UIDS}
jr = rd(f'{SP}/ch17_journal.out'); JR = re.search(r'(\d[\d,]*) rows', jr); JR = JR.group(1) if JR else '(the journal gate\'s row count not in its print)'
led = f'{ROOT}/logic/oral_triage/deu_17_18_shoftim_2026-09-24.md'; LB = os.path.getsize(led); NSRC = int(re.search(r'\*\*read: (\d+) of \1 — COMPLETE\*\*', rd(led)).group(1))
mf = rd(f'{SP}/ch17_manifest.out'); NCL = int(re.search(r'claims (\d+) \|', mf).group(1))
pt = rd(f'{SP}/ch17_patch.out') if os.path.exists(f'{SP}/ch17_patch.out') else ''; PR = re.search(r'by_ref (\d+) by_gloss (\d+)', pt); PR = PR.groups() if PR else ('?', '?')
ink = rd(f'{SP}/ch17_ink.py'); NA = len(re.findall(r'^assert ', ink, re.M)); F1 = int(re.search(r'^(\d+) failing statements', rd(f'{SP}/ch17_ink_run1.out'), re.M).group(1)); F2 = int(re.search(r'^(\d+) failing statements', rd(f'{SP}/ch17_ink_run2.out'), re.M).group(1)); assert F2 == 0
VC = len(re.findall(r'^VERIFIED', rd(f'{SP}/ch17_vc.out'), re.M))
rows = [l.rstrip('\n').split('\t') for l in open(f'{SP}/ch17_timing.tsv', encoding='utf-8') if l[:1].isdigit()]
T15 = [r for r in rows if r[1].startswith('15 ')]; TS = sum(int(r[2]) for r in T15)
