r14b = [l.rstrip('\n').split('\t') for l in open(f'{ROOT}/World/step9/forms_deuteronomy_walk/ch16b_timing.tsv', encoding='utf-8') if l[:1].isdigit()]; T14B = [r for r in r14b if r[1].startswith('14b ')]; TS14B = sum(int(r[2]) for r in T14B)
