rec = sub1(rec, '## 2. WHERE IT STANDS (2026-09-23; #210 sitting 14b newest)', '## 2. WHERE IT STANDS (2026-09-24; #211 sitting 15 newest)')
rec = sub1(rec, '- NUMBERS CLOSED. DEUTERONOMY 1:1-16:22 ON THE TAPE (PUSHED through f730559 — 16 lean).', '- NUMBERS CLOSED. DEUTERONOMY 1:1-16:22 ON THE TAPE (PUSHED through f730559); 17-18 READ AND FROZEN (lean).')
rec = sub1(rec, '- 230 frozen units, standing 2267, hash 8b8fff1fa28953af.', f'- {U1} frozen units, standing {S1}, hash {H1}.')
