wk = wk.rstrip('\n') + f'\n\nSITTING 15 DONE 2026-09-24 — CHAPTERS 17-18 READ AND FROZEN IN THE LEAN FORM (the third sitting of [[lean-pass-ruling]], the first on two chapters): one window; the spine\'s 181 rows (piskaot 147-178, every head in verse order, none headless) and Onkelos\'s 42 whole, 11 outside rows; the ledger deu_17_18_shoftim_2026-09-24.md ({NSRC} sources); {NCL} claims over two units (deu_17_courts_king, deu_18_levi_prophet); the fold {U1} / {S1} / the hash unmoved; the register gate DECLARED {DECL}; the display patch {PR[1]} by gloss + {PR[0]} by reference (the rest owed). THE LESSONS: two chapters are one derive, two dumps and one split; the Name with a geresh cuts as its one letter; the cut misses are found at once; the Hebrew\'s own "ibid."; a two-chapter measure is read compacted; the lean window held for two chapters ({len(T15)} steps, {TS} machine seconds). UNCOMMITTED since f730559. NEXT on his word: the commit; then 15b (the compile of chapters 17-18, lean) after a compaction.\n'
debt = rd(DEBT)
mm = re.search(r'^([^\n]*\(2\) sitting 14b[^\n]*)$', debt, re.M); assert mm and debt.count(mm.group(1)) == 1, 'the lean box line (2)'
L2 = mm.group(1)
debt = debt.replace(L2, L2 + f' (3) sitting 15 (2026-09-24) — CHAPTERS 17-18 READ, LEAN, TWO UNITS: the Sifrei\'s 181 rows (piskaot 147-178) and Onkelos\'s 42 whole, 11 outside rows ({NSRC} sources); NO docket, NO Talmud folio read; the Mishnah rows the spine cites (Sanhedrin 11:2, 2:4, 7:7, Sotah 7:8, Chullin 10:4, 11:2, Zevachim 2:1, Sukkah 5:7) routed to 15b; the display patch small ({PR[1]} by gloss, {PR[0]} by reference — the rest of the two chapters\' glosses OWED); the ten deferred records not written; the full process OWED. 15b (the compile of 17-18): next.')
LINT = {}
for p in (MAP, SD, REC, IDX, DEBT, WALK):
    r = subprocess.run(['python3', f'{ROOT}/logic/solo_tools/gloss_lint.py', p], capture_output=True, text=True); LINT[os.path.basename(p)] = int(re.search(r'(\d+) flag', r.stdout).group(1))
for txt in (ASB, BLOCK, rec, idx, wk, debt): assert '<home>' not in txt and os.path.expanduser('~') not in txt, 'a home path'
assert not re.search(r'[֐-׿]', ASB + BLOCK + debt[debt.index('(3) sitting 15 (2026-09-24)'):debt.index('15b (the compile of 17-18): next.')]), 'NO HEBREW SCRIPT IN THE MAP, THE STATE DOC BLOCK OR THE DEBT LINE'
print(f'THE RECORDS {"CHECKED" if CHECK else "WRITTEN"}: the AS BUILT {len(ASB.encode("utf-8"))} bytes; #211 {len(BLOCK.encode("utf-8"))}; the recovery page {len(rec.encode("utf-8"))}; MEMORY.md {len(idx.encode("utf-8"))}; the walk note {len(wk.encode("utf-8"))}; the debt line; the lints before {LINT}; 14b\'s timing correction {len(T14B)} steps / {TS14B} s (map rows {MB})')
if not CHECK:
    open(MAP, 'a', encoding='utf-8').write(ASB); open(SD, 'a', encoding='utf-8').write(BLOCK); open(REC, 'w', encoding='utf-8').write(rec); open(IDX, 'w', encoding='utf-8').write(idx); open(WALK, 'w', encoding='utf-8').write(wk); open(DEBT, 'w', encoding='utf-8').write(debt)
    L2 = {}
    for p in (MAP, SD, REC, IDX, DEBT, WALK):
        r = subprocess.run(['python3', f'{ROOT}/logic/solo_tools/gloss_lint.py', p], capture_output=True, text=True); L2[os.path.basename(p)] = int(re.search(r'(\d+) flag', r.stdout).group(1))
    assert L2 == LINT, (LINT, L2)
